import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"Syntax & file format","description":"","frontmatter":{},"headers":[],"relativePath":"language/syntax.md","filePath":"language/syntax.md"}'),l={name:"language/syntax.md"};function o(i,e,p,c,r,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="syntax-file-format" tabindex="-1">Syntax &amp; file format <a class="header-anchor" href="#syntax-file-format" aria-label="Permalink to &quot;Syntax &amp; file format&quot;">​</a></h1><p>Megalo scripts are plain-text files (<code>.txt</code>) composed of a sequence of <strong>elements</strong>. This page covers the lexical rules — how tokens are formed, how comments work, and how files are composed.</p><h2 id="file-structure" tabindex="-1">File structure <a class="header-anchor" href="#file-structure" aria-label="Permalink to &quot;File structure&quot;">​</a></h2><p>A Megalo file is a top-to-bottom sequence of elements. There is no required order, but shipped scripts typically follow a convention:</p><ol><li><code>include</code> directives (and optionally a <code>base</code> declaration)</li><li><code>string_table</code> / string includes</li><li><code>engine_data</code>, <code>teams</code>, <code>map_permissions</code></li><li><code>map_object</code> labels</li><li><code>game_options</code>, <code>constants</code></li><li><code>variables</code></li><li><code>hud_widgets</code>, loadouts, statistics</li><li><code>trigger</code> blocks</li></ol><p>Individual element pages are listed under <strong>Elements</strong> in the sidebar.</p><h2 id="the-element-model" tabindex="-1">The element model <a class="header-anchor" href="#the-element-model" aria-label="Permalink to &quot;The element model&quot;">​</a></h2><p>Megalo source is structured as nested elements:</p><ul><li><strong>Block elements</strong> open with a keyword and close with <code>end</code>. The keyword determines which child elements are legal inside.</li><li><strong>Field elements</strong> are single lines inside a block (indented under their parent).</li><li><strong>Leaf elements</strong> like <code>include</code> appear at the top level as standalone lines.</li></ul><p>The set of legal child elements is always determined by the parent. For example, inside a <code>game_options</code> block you may write <code>option</code>, <code>override</code>, <code>player_traits</code>, <code>lock</code>, or <code>hide</code> — but not <code>trigger</code> or <code>variables</code>.</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">game_options</span><span class="megalo-text">                          </span><span class="megalo-comment">; block element opens</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">teams_enabled</span><span class="megalo-text"> </span><span class="megalo-variable">false</span><span class="megalo-text">      </span><span class="megalo-comment">; field element</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">25</span><span class="megalo-text">    </span><span class="megalo-comment">; field element</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">option</span><span class="megalo-text"> </span><span class="megalo-variable">kill_points</span><span class="megalo-text">                </span><span class="megalo-comment">; nested block element</span></span>
<span class="line"><span class="megalo-text">		option_name_kill_points</span></span>
<span class="line"><span class="megalo-text">		option_description_kill_points</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-number">0</span><span class="megalo-text"> points_0 </span><span class="megalo-string">&quot;&quot;</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-number">1</span><span class="megalo-text"> points_1 </span><span class="megalo-string">&quot;&quot;</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span><span class="megalo-text">                               </span><span class="megalo-comment">; closes option</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">player_traits</span><span class="megalo-text"> </span><span class="megalo-variable">leader_traits</span><span class="megalo-text">       </span><span class="megalo-comment">; nested block element</span></span>
<span class="line"><span class="megalo-text">		leader_traits_name leader_traits_description</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-parameter">waypoint</span><span class="megalo-text"> </span><span class="megalo-enumMember">unchanged</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span><span class="megalo-text">                               </span><span class="megalo-comment">; closes player_traits</span></span>
<span class="line"><span class="megalo-keyword">end</span><span class="megalo-text">                                   </span><span class="megalo-comment">; closes game_options</span></span></code></pre></div><p>Some smaller blocks use a flat indented field list rather than nested <code>begin</code>/<code>end</code> pairs:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> slayer_title</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">description</span><span class="megalo-text"> slayer_description</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">icon</span><span class="megalo-text"> k_engine_icon_slayer</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">category</span><span class="megalo-text"> slayer</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2><p>Megalo has <strong>line comments only</strong>. A semicolon starts a comment that runs to the end of the line:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">; This is a comment.</span></span>
<span class="line"><span class="megalo-text">action set my_counter add </span><span class="megalo-number">1</span><span class="megalo-text">  </span><span class="megalo-comment">; inline comment</span></span></code></pre></div><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><p>Megalo source is tokenized into a small set of kinds:</p><table tabindex="0"><thead><tr><th>Token</th><th>Example</th></tr></thead><tbody><tr><td>Identifier</td><td><code>my_counter</code>, <code>player_died</code>, <code>set_to</code></td></tr><tr><td>Member separator</td><td><code>.</code> in <code>current_player.score</code></td></tr><tr><td>Quoted string</td><td><code>&quot;ctf_flag_spawn&quot;</code>, <code>&quot;Slayer&quot;</code></td></tr><tr><td>Integer</td><td><code>0</code>, <code>25</code>, <code>-1</code>, <code>+1</code></td></tr><tr><td>Floating point</td><td><code>1.5</code>, <code>+3.5</code></td></tr><tr><td>Comment</td><td><code>; ...</code></td></tr></tbody></table><h2 id="string-literals" tabindex="-1">String literals <a class="header-anchor" href="#string-literals" aria-label="Permalink to &quot;String literals&quot;">​</a></h2><p>Double-quoted strings support these escape sequences:</p><table tabindex="0"><thead><tr><th>Escape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>\\n</code></td><td>Newline</td></tr><tr><td><code>\\r</code></td><td>Carriage return</td></tr><tr><td><code>\\t</code></td><td>Tab</td></tr><tr><td><code>\\&quot;</code></td><td>Literal quote</td></tr><tr><td><code>\\\\</code></td><td>Literal backslash</td></tr></tbody></table><p>Any other <code>\\x</code> sequence passes through the backslash and the character literally.</p><p>Quoted strings are Megalo <strong>string literals</strong>. The lexer decodes escape sequences and passes the resulting text to the compiler. Literals appear in three common roles:</p><table tabindex="0"><thead><tr><th>Role</th><th>Example</th></tr></thead><tbody><tr><td>Include path</td><td><code>include &quot;strings/slayer_strings.txt&quot;</code></td></tr><tr><td>String table entry</td><td><code>slayer_title &quot;Slayer&quot;</code> inside <a href="/MegaloEvolved/beta/docs/language/elements/string-table"><code>string_table</code></a></td></tr><tr><td>Action operand</td><td><code>action hud_post_message everyone none &quot;CTF&quot;</code></td></tr></tbody></table><h3 id="string-table-symbols-vs-inline-literals" tabindex="-1">String table symbols vs inline literals <a class="header-anchor" href="#string-table-symbols-vs-inline-literals" aria-label="Permalink to &quot;String table symbols vs inline literals&quot;">​</a></h3><p>Most user-facing text in shipped scripts uses <strong>string table symbols</strong> — unquoted identifiers that point at localized entries:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">string_table</span><span class="megalo-text"> </span><span class="megalo-enumMember">english</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-variable">slayer_title</span><span class="megalo-text"> </span><span class="megalo-string">&quot;Slayer&quot;</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-variable">slayer_description</span><span class="megalo-text"> </span><span class="megalo-string">&quot;Score points by killing players on the opposing team.&quot;</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> </span><span class="megalo-variable">slayer_title</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">description</span><span class="megalo-text"> </span><span class="megalo-variable">slayer_description</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">general</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">hud_post_message</span><span class="megalo-text"> </span><span class="megalo-enumMember">everyone</span><span class="megalo-text"> </span><span class="megalo-variable">none</span><span class="megalo-text"> invasion_title_spartan</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>The <code>string_table</code> block defines the literal text once per language. Everywhere else, the script references the symbol (<code>slayer_title</code>, <code>invasion_title_spartan</code>) rather than repeating quoted text. That keeps gametype names, HUD strings, and objectives localizable.</p><p>Some action operands accept <strong>inline literals</strong> instead — quoted text embedded directly in the trigger:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action hud_post_message everyone none </span><span class="megalo-string">&quot;CTF&quot;</span></span>
<span class="line"><span class="megalo-text">action hud_widget_set_text watermark </span><span class="megalo-string">&quot;Environment Artist&quot;</span></span></code></pre></div><p>The compiler stores inline literal text in the variant&#39;s script string table at compile time. Inline literals <strong>cannot be localized</strong> — the quoted text is fixed when you compile. Under <a href="/MegaloEvolved/beta/docs/language/compiler-settings#string-literal-strictness">strict compiler settings</a>, literals where a string-table symbol is expected are forbidden. They are still handy during development (one-off messages, tooling scripts, <code>%n</code> format strings), but prefer <code>string_table</code> symbols when finalizing gametypes.</p><h3 id="format-placeholders" tabindex="-1">Format placeholders <a class="header-anchor" href="#format-placeholders" aria-label="Permalink to &quot;Format placeholders&quot;">​</a></h3><p>Several string operands are <a href="/MegaloEvolved/beta/docs/language/enums/dynamic-strings">dynamic strings</a>: the text may contain <code>%</code> placeholders (<code>%n</code>, <code>%p</code>, <code>%t</code>, <code>%o</code>, <code>%s</code>), and matching reference operands follow the string in the action:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action player_set_objective current_player </span><span class="megalo-string">&quot;+</span><span class="megalo-regexp">%n</span><span class="megalo-string">&quot;</span><span class="megalo-text"> score_to_win_round</span></span></code></pre></div><p>At runtime the engine substitutes the player&#39;s score-to-win value into the <code>%n</code> slot, producing text like <code>+25</code>. See <a href="/MegaloEvolved/beta/docs/language/enums/dynamic-strings">Dynamic strings</a> for the full placeholder table, limits, and which actions use them.</p><h3 id="strict-compiler" tabindex="-1">Strict compiler <a class="header-anchor" href="#strict-compiler" aria-label="Permalink to &quot;Strict compiler&quot;">​</a></h3><p>Many fields expect a string-table <strong>symbol</strong>, not a literal. For example, <code>engine_data name slayer_title</code> is normal; <code>engine_data name &quot;Slayer&quot;</code> compiles in MegaloEdit but emits a warning that the internal build farm would reject it. See <a href="/MegaloEvolved/beta/docs/language/compiler-settings#string-literal-strictness">String literal strictness</a>.</p><p>See also <a href="/MegaloEvolved/beta/docs/language/references#string-table-references">String table references</a> for how string operands are resolved in actions and conditions.</p><h2 id="identifiers-and-naming" tabindex="-1">Identifiers and naming <a class="header-anchor" href="#identifiers-and-naming" aria-label="Permalink to &quot;Identifiers and naming&quot;">​</a></h2><p>Variable, constant, trigger, and element names:</p><ul><li>May contain alphanumeric characters and underscores</li><li>Must <strong>not</strong> start with a digit</li><li>Must be <strong>unique</strong> across the shared namespace (variables, constants, triggers, game options, and other named elements cannot collide)</li></ul><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">red_score</span><span class="megalo-text"> </span><span class="megalo-number">0</span><span class="megalo-text">       </span><span class="megalo-comment">; valid</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">team3_score</span><span class="megalo-text"> </span><span class="megalo-number">0</span><span class="megalo-text">     </span><span class="megalo-comment">; valid</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> 4team_score </span><span class="megalo-number">0</span><span class="megalo-text">     </span><span class="megalo-comment">; invalid — starts with a digit</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="includes" tabindex="-1">Includes <a class="header-anchor" href="#includes" aria-label="Permalink to &quot;Includes&quot;">​</a></h2><p>The <code>include</code> directive merges another source file into the current script at compile time:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/slayer_strings.txt&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;includes/multiplayer_loadouts.txt&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;includes/sudden_death_pre.txt&quot;</span></span></code></pre></div><p>Included files contribute their elements to the final script. This is how Bungie shared common logic (loadouts, sudden death, achievements) across many gametypes.</p><p>A path that was already included earlier in the same script is skipped (resolved only once). See <a href="/MegaloEvolved/beta/docs/language/elements/include"><code>include</code></a> for details, including cycles.</p><p>String tables are often organized as a language-agnostic wrapper that includes per-language files:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/common_strings.txt&quot;</span></span></code></pre></div><p>Where <code>strings/common_strings.txt</code> is itself a list of plain includes — one per language:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;english/common_strings.txt&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;french/common_strings.txt&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;german/common_strings.txt&quot;</span></span></code></pre></div><p>Each language file opens with <code>string_table &lt;language&gt;</code> and defines the translated strings for that locale.</p><h3 id="localized-include" tabindex="-1">localized_include <a class="header-anchor" href="#localized-include" aria-label="Permalink to &quot;localized_include&quot;">​</a></h3><p>MegaloEdit recognizes a second include keyword:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">localized_include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/english/slayer_strings.txt&quot;</span></span></code></pre></div><p>Syntax mirrors <code>include</code> — a quoted path relative to the current file.</p><p>Localized includes are just like regular includes, except they are <strong>optional when the file is missing</strong> in lenient compile mode. If the compiler cannot find the path, it emits a warning and skips the include instead of failing the compile. Plain <code>include</code> of a missing file is always a hard error.</p><p>In strict compile mode, missing localized includes error the same way. MegaloEdit always uses lenient mode — see <a href="/MegaloEvolved/beta/docs/language/compiler-settings">Compiler settings</a>.</p><p>When the file <strong>does</strong> exist, <code>localized_include</code> loads and parses it the same as <code>include</code>. The keyword does not survive into compiled variant data; it is resolved entirely at compile time.</p><p><strong>No shipped HREK script uses it.</strong> Bungie used wrapper files and plain <code>include</code> instead (see above). For Reach scripting, that wrapper pattern is the authoritative approach.</p><h2 id="base-files" tabindex="-1">Base files <a class="header-anchor" href="#base-files" aria-label="Permalink to &quot;Base files&quot;">​</a></h2><p>Some scripts begin with a <code>base</code> directive instead of (or in addition to) includes:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">base</span><span class="megalo-text"> </span><span class="megalo-string">&quot;ctf.mglo&quot;</span></span></code></pre></div><p>This inherits a compiled parent variant rather than merging source text. See <a href="/MegaloEvolved/beta/docs/language/base-files">Base files</a> for the full explanation.</p><h2 id="indentation" tabindex="-1">Indentation <a class="header-anchor" href="#indentation" aria-label="Permalink to &quot;Indentation&quot;">​</a></h2><p>Megalo uses tabs for indentation inside block elements. Indentation is cosmetic — the parser uses keywords (<code>end</code>, element names) to determine structure, not whitespace. Shipped scripts consistently use tabs.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/elements/string-table">string_table</a> — defining localized strings</li><li><a href="/MegaloEvolved/beta/docs/language/compiler-settings">Compiler settings</a> — MegaloEdit compile flags (<code>enforceLocalizedIncludes</code>, etc.)</li><li><a href="/MegaloEvolved/beta/docs/language/base-files">Base files</a> — inheritance from compiled variants</li><li><a href="/MegaloEvolved/beta/docs/language/examples">Example scripts</a> — annotated minimal scripts</li><li><a href="/MegaloEvolved/beta/docs/language/references#string-table-references">References</a> — string operands in actions</li></ul>`,69)])])}const u=a(l,[["render",o]]);export{m as __pageData,u as default};
